impl OperatorControlAuthority{pub fn new(authority_id:impl Into<String>,audit_genesis:impl Into<String>)->Result<Self,AssuranceError>{let authority_id=authority_id.into();validate_identifier(&authority_id,"operator control authority")?;Ok(Self{authority_id,audit:AssuranceAuditChain::new(audit_genesis)?})}pub fn certify(&mut self,control:&OperatorControlPlane)->Result<OperatorControlCertificate,AssuranceError>{control.audit.verify()?;if control.state!=OperatorControlState::Sealed||control.receipts.is_empty()||control.incidents.values().any(IncidentRecord::is_open){return Err(AssuranceError::ClosureDenied("operator control is not sealed".into()));}let command_receipt_root_sha256=hash_serializable(&control.receipts)?;let incident_root_sha256=hash_serializable(&control.incidents)?;let seed=hash_serializable(&(&self.authority_id,&control.integration.certificate_sha256,&command_receipt_root_sha256,&incident_root_sha256,control.audit.tail_hash()))?;let certificate_id=format!("operator-control-{}",&seed[..24]);self.audit.append(AssuranceAuditEvent{action:"operator_control_certified".into(),subject_id:certificate_id.clone(),outcome:"sealed".into(),metadata:BTreeMap::from([("integration_certificate_sha256".into(),control.integration.certificate_sha256.clone())])})?;let certificate_sha256=hash_serializable(&(&certificate_id,&control.integration.certificate_sha256,control.state,&command_receipt_root_sha256,&incident_root_sha256,control.audit.tail_hash()))?;let c=OperatorControlCertificate{certificate_id,integration_certificate_sha256:control.integration.certificate_sha256.clone(),final_state:control.state,command_receipt_root_sha256,incident_root_sha256,control_audit_tail_hash:control.audit.tail_hash().into(),certificate_sha256};c.verify()?;Ok(c)}pub fn audit(&self)->&AssuranceAuditChain{&self.audit}}
